29	// Sink is a sink for writing snapshot data to a Snapshot store.
30	//
31	// This sink is adaptive. It can handle multiple types of snapshot data,
32	// including full database snapshots, incremental snapshots (WAL files),
33	// and snapshot installs (DB file plus WAL files).
34	type Sink struct {
35		dir    string
36		meta   *raft.SnapshotMeta
37		opened bool
38	
39		snapDirPath    string
40		snapTmpDirPath string
41	
42		buf    bytes.Buffer
43		header *proto.SnapshotHeader
44		sinkW  sinker
45	
46		// localWALDir is set when the header indicates an IncrementalFileSnapshot.
47		// In this case, no data follows the header; the WAL directory is moved on Close.
48		localWALDir string
49	
50		// isNoop is set when the header indicates a NoopSnapshot.
51		// No data follows the header; a data.noop sentinel file is created on Close.
52		isNoop bool
53	
54		fc fullController
55	
56		logger *log.Logger
57	}
58	
59	// NewSink creates a new Sink object. It takes the root snapshot directory
60	// and the snapshot metadata.
61	func NewSink(dir string, meta *raft.SnapshotMeta, fc fullController) *Sink {
62		return &Sink{
63			dir:    dir,
64			meta:   meta,
65			fc:     fc,
66			logger: log.New(log.Writer(), "[snapshot-sink] ", log.LstdFlags),
67		}
68	}
69	
70	// Open opens the sink for writing.
71	func (s *Sink) Open() error {
72		if s.opened {
73			return nil
74		}
75		s.opened = true
76	
77		// Make temp snapshot directory
78		s.snapDirPath = filepath.Join(s.dir, s.meta.ID)
79		s.snapTmpDirPath = tmpName(s.snapDirPath)
80		if err := os.MkdirAll(s.snapTmpDirPath, 0755); err != nil {
81			return err
82		}
83		return nil
84	}
85	
86	// ID returns the ID of the snapshot.
87	func (s *Sink) ID() string {
88		return s.meta.ID
89	}
90	
91	// Write writes snapshot data to the sink.
92	func (s *Sink) Write(p []byte) (n int, err error) {
93		// If we don't yet have a header, try to decode one.
94		if s.header == nil {
95			n, err := s.buf.Write(p)
96			if err != nil {
97				return n, err
98			}
99	
100			if err := s.processHeader(); err != nil {
101				return n, err
102			}
103	
104			if s.header == nil {
105				// Still waiting for more data to form a complete header.
106				return n, nil
107			}
108	
109			// We have a header, figure out what to do with it.
110			switch p := s.header.Payload.(type) {
111			case *proto.SnapshotHeader_Full:
112				s.sinkW = NewFullSink(s.snapTmpDirPath, p.Full)
113			case *proto.SnapshotHeader_Incremental:
114				if s.fc != nil {
115					fullNeeded, err := s.fc.FullNeeded()
116					if err != nil {
117						return n, err
118					}
119					if fullNeeded {
120						return n, fmt.Errorf("full snapshot needed before incremental can be applied")
121					}
122				}
123				s.sinkW = NewIncrementalSink(s.snapTmpDirPath, p.Incremental.WalHeader)
124			case *proto.SnapshotHeader_IncrementalFile:
125				if s.fc != nil {
126					fullNeeded, err := s.fc.FullNeeded()
127					if err != nil {
128						return n, err
129					}
130					if fullNeeded {
131						return n, fmt.Errorf("full snapshot needed before incremental can be applied")
132					}
133				}
134				// No data follows this header type. Any leftover bytes are an error.
135				if s.buf.Len() > 0 {
136					return n, fmt.Errorf("unexpected data after incremental file header")
137				}
138				s.localWALDir = p.IncrementalFile.WalDirPath
139				return n, nil
140			case *proto.SnapshotHeader_Noop:
141				if s.fc != nil {
142					fullNeeded, err := s.fc.FullNeeded()
143					if err != nil {
144						return n, err
145					}
146					if fullNeeded {
147						return n, fmt.Errorf("full snapshot needed before noop can be applied")
148					}
149				}
150				// No data follows this header type. Any leftover bytes are an error.
151				if s.buf.Len() > 0 {
152					return n, fmt.Errorf("unexpected data after noop header")
153				}
154				s.isNoop = true
155				return n, nil
156			default:
157				return n, fmt.Errorf("unrecognized snapshot header payload")
158			}
159	
160			// Prep and preload the streaming sink.
161			if err := s.sinkW.Open(); err != nil {
162				return n, err
163			}
164			if _, err := s.buf.WriteTo(s.sinkW); err != nil {
165				return n, err
166			}
167			return n, nil
168		}
169	
170		// We have a header, just write directly to the underlying sink.
171		if s.sinkW == nil {
172			// IncrementalFile or Noop path — no data expected after header.
173			if s.isNoop {
174				return 0, fmt.Errorf("unexpected data after noop header")
175			}
176			return 0, fmt.Errorf("unexpected data after incremental file header")
177		}
178		return s.sinkW.Write(p)
179	}
180	
181	// Close closes the sink.
182	func (s *Sink) Close() error {
183		if !s.opened {
184			return nil
185		}
186		s.opened = false
187	
188		if s.sinkW == nil && s.localWALDir == "" && !s.isNoop {
189			// Header was never fully received; clean up the temp directory.
190			return os.RemoveAll(s.snapTmpDirPath)
191		}
192	
193		if s.isNoop {
194			// NoopSnapshot: create the data.noop sentinel file.
195			noopPath := filepath.Join(s.snapTmpDirPath, noopfileName)
196			f, err := os.Create(noopPath)
197			if err != nil {
198				return err
199			}
200			if err := f.Close(); err != nil {
201				return err
202			}
203		} else if s.localWALDir != "" {
204			// IncrementalFileSnapshot: atomically move the WAL directory into the
205			// snapshot directory, then redistribute the WAL files.
206			movedDir := filepath.Join(s.snapTmpDirPath, "wal-incoming")
207			if err := os.Rename(s.localWALDir, movedDir); err != nil {
208				return err
209			}
210	
211			walMatches, err := filepath.Glob(filepath.Join(movedDir, "*"+walfileSuffix))
212			if err != nil {
213				return fmt.Errorf("globbing for WAL files in moved directory: %w", err)
214			}
215			if len(walMatches) > 1 {
216				s.logger.Printf("found %d WAL files in moved directory, processing multi-WAL snapshot",
217					len(walMatches))
218			}
219	
220			for _, srcPath := range walMatches {
221				name := filepath.Base(srcPath)
222				dstPath := filepath.Join(s.snapTmpDirPath, name)
223				if err := os.Rename(srcPath, dstPath); err != nil {
224					return err
225				}
226				if !db.IsValidSQLiteWALFile(dstPath) {
227					return fmt.Errorf("%s is not a valid SQLite WAL file", name)
228				}
229			}
230	
231			if err := os.Remove(movedDir); err != nil {
232				return err
233			}
234		} else {
235			if err := s.sinkW.Close(); err != nil {
236				return err
237			}
238		}
239	
240		if err := writeMeta(s.snapTmpDirPath, s.meta); err != nil {
241			return err
242		}
243	
244		if err := os.Rename(s.snapTmpDirPath, s.snapDirPath); err != nil {
245			return err
246		}
247	
248		if s.fc != nil {
249			if err := s.fc.UnsetFullNeeded(); err != nil {
250				return err
251			}
252		}
253		return syncDirMaybe(s.dir)
254	}
255	
256	// Cancel cancels the sink.
257	func (s *Sink) Cancel() error {
258		if !s.opened {
259			return nil
260		}
261		s.opened = false
262		if s.sinkW != nil {
263			if err := s.sinkW.Close(); err != nil {
264				return err
265			}
266			s.sinkW = nil
267		}
268		return os.RemoveAll(s.snapTmpDirPath)
269	}
