111	func Test_WriteCRC32SumFileRoundTrip(t *testing.T) {
112		path := filepath.Join(t.TempDir(), "checksum")
113		var sum uint32 = 0x1a2b3c4d
114	
115		if err := WriteCRC32SumFile(path, sum); err != nil {
116			t.Fatalf("WriteCRC32SumFile failed: %v", err)
117		}
118	
119		// File should contain the hex string.
120		b, err := os.ReadFile(path)
121		if err != nil {
122			t.Fatalf("reading checksum file: %v", err)
123		}
124		if got, want := string(b), "1a2b3c4d"; got != want {
125			t.Errorf("file contents = %q, want %q", got, want)
126		}
127	
128		// Round-trip through ReadCRC32SumFile.
129		got, err := ReadCRC32SumFile(path)
130		if err != nil {
131			t.Fatalf("ReadCRC32SumFile failed: %v", err)
132		}
133		if got != sum {
