	b, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	var sum uint32
	if _, err := fmt.Sscanf(string(b), "%08x", &sum); err != nil {
		return 0, fmt.Errorf("invalid checksum file: %w", err)
	}
	return sum, nil
}
