				if err != nil {
					return n, err
				}
				if fullNeeded {
					return n, fmt.Errorf("full snapshot needed before incremental can be applied")
				}
			}
			s.sinkW = NewIncrementalSink(s.snapTmpDirPath, p.Incremental.WalHeader)
